#include "family_continuation_people4.hpp"
#include "resident/domains/actor_foundation/model.hpp"
#include <algorithm>
namespace hanmo::resident {
bool FamilyContinuationPeopleRead4::bound_to(const CommonStore& c)const noexcept{return &ages_.common==&c&&&ages_.control.common==&c&&life_.bound_to(c);}
bool FamilyContinuationPeopleRead4::bound_to(const CommonStore& c,const FamilyDeathState& d)const noexcept{return &ages_.common==&c&&&ages_.control.common==&c&&life_.bound_to(c,d);}
Outcome<WorldMoment> FamilyContinuationPeopleRead4::read_current_moment()const{auto at=clock_.read_current_moment();if(!at.ok)return at;auto actual=life_.read_current_moment();if(!actual.ok)return actual;auto same=compare_world_moments(at.value,actual.value);if(!same.ok||same.value!=0)return {false,{},common_failure("FamilyContinuationClockMismatch",{},ErrorKind::internal).error};return at;}
Outcome<LifeAgeBasisSnapshot> FamilyContinuationPeopleRead4::read_current_age(const StableId& actor)const{auto at=read_current_moment();if(!at.ok)return {false,{},at.error};return read_life_age_basis(ages_,actor,at.value);}
Outcome<LifeAgeBasisSnapshot> FamilyContinuationPeopleRead4::read_age_before_original_fact(const StableId& actor,Integer tick,const SourceRef& fact)const{auto at=read_current_moment();if(!at.ok)return {false,{},at.error};return read_life_age_basis_at_original_fact(ages_,actor,tick,fact,clock_);}
Outcome<ActorPresenceRead> FamilyContinuationPeopleRead4::presence(const StableId& actor,Integer tick,const SourceRef* boundary,bool historical,const CommonActualFactPrefix* prefix)const{
 const auto& c=ages_.common;auto at=read_current_moment();if(!at.ok)return {false,{},at.error};auto fail=[&](const StableId& code)->Outcome<ActorPresenceRead>{return {false,{},common_failure(code,actor,ErrorKind::internal).error};};
 if(tick<0||tick>at.value.half_day_tick||(!historical&&tick!=at.value.half_day_tick))return fail("FamilyContinuationPresenceTimeMismatch");
 // The same age/origin reader proves this actor existed before the actual
 // consumer cut. Declared age never needs a fabricated Common birth_tick.
 auto age=prefix?read_age_at_original_prefix(actor,tick,*prefix):historical?read_age_before_original_fact(actor,tick,*boundary):read_current_age(actor);if(!age.ok)return {false,{},age.error};
 const auto* person=c.state().actors.find(actor);if(!person)return fail("UnknownPresenceActor");ActorPresenceRead out;out.source_identity=c.state().identity;out.actor_id=actor;out.observed_tick=tick;if(boundary)out.before_fact_id=boundary->id;
 if(!ages_.foundation.actor_start_context.actor_age_bases.find(actor)){const auto* created=c.state().facts.find(actor);if(!created||created->kind!="actor_creation"||(created->domain!="family"&&created->domain!="family_birth")||!person->created_tick||*person->created_tick>tick)return fail("FamilyContinuationCreationSourceRequired");out.creation_fact_id=actor;out.created_tick=*person->created_tick;}
 auto death=life_.read_actor_death(actor);if(!death.ok)return {false,{},death.error};if(!death.value){if(!person->alive)return {false,{},common_failure("FamilyContinuationInitialLifeSourceRequired",actor,ErrorKind::unsupported_capability).error};out.alive=true;return {true,std::move(out),{}};}
 const auto& actual=*death.value;if(actual.effective_at.kind!=ActorFoundationAt::Kind::exact_moment)return fail("FamilyLife4ExactDeathRequired");bool died=false;if(prefix){auto included=actual_common_fact_in_prefix(c,actual.cause_ref,*prefix);if(!included.ok)return {false,{},included.error};died=included.value;}else{const auto& order=c.state().facts.order();const auto cause=std::find(order.begin(),order.end(),actual.cause_ref.id);const auto end=historical?std::find(order.begin(),order.end(),boundary->id):order.end();if(cause==order.end()||(historical&&end==order.end()))return fail("FamilyContinuationDeathBoundaryRequired");died=cause<end;}
 if((died&&actual.effective_at.exact_moment.half_day_tick>tick)||(!died&&actual.effective_at.exact_moment.half_day_tick<tick))return fail("FamilyContinuationDeathTimeMismatch");out.alive=!died;if(died)out.death_cause_fact_id=actual.cause_ref.id;return {true,std::move(out),{}};
}
Outcome<LifeAgeBasisSnapshot> FamilyContinuationPeopleRead4::read_age_at_original_prefix(const StableId& actor,Integer tick,const CommonActualFactPrefix& prefix)const{return read_life_age_basis_at_original_prefix(ages_,actor,tick,prefix,clock_);}
Outcome<ActorPresenceRead> FamilyContinuationPeopleRead4::read_presence_at_original_prefix(const StableId& actor,Integer tick,const CommonActualFactPrefix& prefix)const{return presence(actor,tick,nullptr,true,&prefix);}
Outcome<ActorPresenceRead> FamilyContinuationPeopleRead4::read_current_presence(const StableId& actor)const{auto at=read_current_moment();if(!at.ok)return {false,{},at.error};return presence(actor,at.value.half_day_tick,nullptr,false);}
Outcome<ActorPresenceRead> FamilyContinuationPeopleRead4::read_presence_before_original_fact(const StableId& actor,Integer tick,const SourceRef& boundary)const{return presence(actor,tick,&boundary,true);}
Outcome<FamilyDecisionAgeSources4> capture_family_decision_ages4(const FamilyContinuationPeopleRead4& people,const StableId& a,const StableId& b){
 if(a==b)return {false,{},common_failure("FamilyDecisionDistinctPeopleRequired").error};FamilyDecisionAgeSources4 out;
 for(const auto* actor:{&a,&b}){auto present=people.read_current_presence(*actor);if(!present.ok)return {false,{},present.error};if(!present.value.alive)return {false,{},common_failure("FamilyDecisionLivingAdultRequired",*actor).error};auto age=people.read_current_age(*actor);if(!age.ok)return {false,{},age.error};if(age.value.age_years<18)return {false,{},common_failure("FamilyDecisionLivingAdultRequired",*actor).error};(*actor==a?out.predecessor:out.successor)=std::move(age.value.ref);}return {true,std::move(out),{}};
}
Status validate_family_decision_ages4(const FamilyContinuationPeopleRead4& people,const CommonStore& common,const FamilyDecisionAgeSources4& saved,const StableId& a,const StableId& b,Integer tick,const StableId& before){
 if(!people.bound_to(common))return common_failure("FamilyContinuationCandidateMismatch",{},ErrorKind::internal);if(a==b)return common_failure("FamilyDecisionDistinctPeopleRequired");const auto* h=before.empty()?nullptr:common.state().facts.find(before);if(!before.empty()&&!h)return common_failure("FamilyDecisionOriginalBoundaryRequired",before,ErrorKind::internal);
 auto now=people.read_current_moment();if(!now.ok)return {false,{},now.error};if(before.empty()&&tick!=now.value.half_day_tick)return common_failure("StaleFamilyDecisionAgeSource");
 for(const auto* actor:{&a,&b}){auto present=before.empty()?people.read_current_presence(*actor):people.read_presence_before_original_fact(*actor,tick,{h->domain,h->kind,before});if(!present.ok)return {false,{},present.error};if(!present.value.alive)return common_failure("FamilyDecisionLivingAdultRequired",*actor);auto age=before.empty()?people.read_current_age(*actor):people.read_age_before_original_fact(*actor,tick,{h->domain,h->kind,before});if(!age.ok)return {false,{},age.error};if(age.value.age_years<18)return common_failure("FamilyDecisionLivingAdultRequired",*actor);if(!same_life_age_basis_ref(age.value.ref,*actor==a?saved.predecessor:saved.successor))return common_failure("FamilyDecisionAgeBasisChanged",*actor,ErrorKind::internal);}return common_success();
}

}
